package com.lmspilot.identity.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="scoped_role_assignments",indexes={@Index(name="idx_scoped_role_user",columnList="user_id"),@Index(name="idx_scoped_role_scope",columnList="scope_type,scope_id")}) public class ScopedRoleAssignmentEntity { @Id public UUID id=UUID.randomUUID(); @Column(name="user_id",nullable=false) public UUID userId; @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="role_id",nullable=false) public RoleEntity role; @Enumerated(EnumType.STRING) @Column(name="scope_type",nullable=false,length=30) public ScopeType scopeType=ScopeType.SYSTEM; @Column(name="scope_id") public UUID scopeId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=10) public GrantEffect effect=GrantEffect.ALLOW; public Instant validFrom; public Instant validUntil; @Column(nullable=false) public UUID createdBy; @Column(nullable=false) public Instant createdAt=Instant.now(); public ScopedRoleAssignmentEntity(){} }
